def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (everything after '-' in the version part)
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert all-digit identifiers to integers for proper comparison
            prerelease_parsed = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))  # 0 prefix for numeric
                else:
                    prerelease_parsed.append((1, identifier))  # 1 prefix for non-numeric
            prerelease_tuple = tuple(prerelease_parsed)
        else:
            prerelease_tuple = None

        return (version_nums, prerelease_tuple)

    def sort_key(v):
        parsed = parse_version(v)
        version_nums, prerelease_tuple = parsed

        # For sorting: version without prerelease comes after version with prerelease
        # So we need to invert the prerelease presence
        if prerelease_tuple is None:
            # No pre-release: sort after (use a tuple that sorts after any prerelease)
            return (version_nums, (2,))
        else:
            # Has pre-release: sort before (use 1 as marker)
            return (version_nums, (1, prerelease_tuple))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

